def hilbertValues (A : I → J → ℝ) : Set ℝ :=
  {z | ∃ (n : ℕ) (x : I → Fin n → ℝ) (y : J → Fin n → ℝ),
    (∀ i, ∑ k, x i k ^ 2 ≤ 1) ∧ (∀ j, ∑ k, y j k ^ 2 ≤ 1) ∧
    z = |∑ i, ∑ j, A i j * ∑ k, x i k * y j k|}

